const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const { Pool } = require('pg');
const fs = require('fs');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
    // Connexion plus tolérante (téléphone en veille, Wi-Fi/4G qui coupe une seconde) :
    pingInterval: 25000,
    pingTimeout: 60000,
    // Après une courte coupure, le joueur retrouve la MÊME session (même id, mêmes salons,
    // événements manqués renvoyés) : la partie continue sans aucun retour au salon.
    connectionStateRecovery: { maxDisconnectionDuration: 2 * 60 * 1000, skipMiddlewares: false }
});

app.use(express.json({ verify: (req, res, buf) => { if (req.originalUrl && req.originalUrl.startsWith('/api/stripe/')) req.rawBody = buf; } }));
// Fichiers du serveur jamais servis au public (code source, config)
app.use((req, res, next) => {
    if (/^\/(server\.js|package(-lock)?\.json|\.env|\.git|node_modules)(\/|$)/i.test(req.path)) return res.status(404).end();
    next();
});
// La page d'accueil est servie par la route « / » plus bas (balises Google ajoutées à la volée)
app.use(express.static(__dirname, { index: false }));

app.get('/api/music-tracks', (req, res) => {
    try {
        const musicDir = path.join(__dirname, 'music');
        if (!fs.existsSync(musicDir)) {
            return res.json({ ok:true, tracks:[], count:0, missingFolder:true });
        }

        const files = fs.readdirSync(musicDir)
            .filter(name => /^track_\d{3}\.mp3$/i.test(name))
            .sort((a,b) => a.localeCompare(b, undefined, { numeric:true }));

        res.json({
            ok:true,
            count:files.length,
            tracks:files.map(name => `/music/${name}`)
        });
    } catch (e) {
        res.status(500).json({ ok:false, tracks:[], count:0, error:e.message });
    }
});


/* ================= Comptes utilisateurs (Postgres + JWT) ================= */
// La base vit en dehors de Render (Neon / Supabase / etc.) via DATABASE_URL,
// donc les comptes et le rating survivent aux redéploiements et aux mises en veille.

const JWT_SECRET = process.env.JWT_SECRET || 'change-this-secret-in-production';
const JWT_EXPIRES_IN = '30d';

if (!process.env.DATABASE_URL) {
    console.warn("⚠️  Aucune variable DATABASE_URL définie : configure-la avec ta connection string Postgres (Neon/Supabase) pour que les comptes soient persistés.");
}

const pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    ssl: process.env.DATABASE_URL ? { rejectUnauthorized: false } : false
});

async function initDb() {
    await pool.query(`
        CREATE TABLE IF NOT EXISTS users (
            id SERIAL PRIMARY KEY,
            pseudo TEXT UNIQUE NOT NULL,
            email TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            rating INTEGER NOT NULL DEFAULT 1000,
            wins INTEGER NOT NULL DEFAULT 0,
            losses INTEGER NOT NULL DEFAULT 0,
            created_at TIMESTAMPTZ NOT NULL DEFAULT now()
        );
    `);

    await pool.query(`
        CREATE TABLE IF NOT EXISTS dle_profiles (
            universe_key TEXT NOT NULL,
            norm_name TEXT NOT NULL,
            display_name TEXT NOT NULL,
            attrs JSONB NOT NULL,
            source TEXT NOT NULL DEFAULT 'fandom',
            updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
            PRIMARY KEY (universe_key, norm_name)
        );
    `);

    await pool.query(`
        CREATE TABLE IF NOT EXISTS character_images (
            universe_key TEXT NOT NULL,
            norm_name TEXT NOT NULL,
            display_name TEXT NOT NULL,
            image_url TEXT,
            source_url TEXT,
            status TEXT NOT NULL DEFAULT 'ok',
            updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
            PRIMARY KEY (universe_key, norm_name)
        );
    `);
}

initDb()
    .then(() => console.log("Base de données prête (table 'users' OK)."))
    .catch(err => {
        console.error("Erreur d'initialisation de la base de données :", err);
    });


