function arcDisplayName(u, name) {
    try {
        const pool = (typeof RG_POOLS_V2 !== 'undefined' && RG_POOLS_V2[u]) || [];
        if (!pool.length) return name;
        const c = rgCanonicalInput(u, name, pool);
        return pool.find(n => normalizeRG(n) === c) || name;
    } catch (_) { return name; }
}


