    if (b.adsClient !== undefined) { const a = String(b.adsClient).trim(); if (a && !/^ca-pub-\d{10,20}$/.test(a)) return res.json({ ok: false, error: 'ID AdSense invalide (ex : ca-pub-1234567890123456).' }); c.adsClient = a; }
