const pmBaseName = n => String(n || '')
    .replace(/\s+[—–-]\s+.*$/, '')
    .replace(/\s+prime$/i, '')
    .replace(/\s+(?:gear\s*5|forme\s+finale|forme\s+ultime|fin\s+de\s+série|post-purgatoire|ailes\s+complètes|the\s+one\s+ultimate|adulte)$/i, '')
    .trim();

let PM_POWER = null;
function pmPower() {
    if (PM_POWER) return PM_POWER;
    PM_POWER = [];

    for (const u of Object.keys(ARC_UNIVERSE_ANIME)) {
        if (u === 'pokemon') {
            const ratings = { ...(ENCHERE_POWER_OVERRIDES[u] || {}), ...(PM_POWER_OVERRIDES[u] || {}) };
            const seen = new Map();
            for (const [name, value] of Object.entries(ratings)) {
                const display = arcDisplayName(u, pmBaseName(name));
                const key = normalizeRG(display);
                if (!key) continue;
                const old = seen.get(key);
                if (!old || Number(value) > old.value) seen.set(key, { u, name:display, base:display, value:Number(value) || 0 });
            }
            PM_POWER.push(...seen.values());
            continue;
        }

        const ratings = { ...(ENCHERE_POWER_OVERRIDES[u] || {}), ...(PM_POWER_OVERRIDES[u] || {}) };
        const seen = new Map();
        for (const [name, value] of Object.entries(ratings)) {
            const cleaned = pmBaseName(name);
            const display = arcDisplayName(u, cleaned);
            const key = normalizeRG(display);
            if (!key) continue;
            const row = { u, name:display, base:display, value:Math.max(1, Math.min(100, Number(value) || 0)) };
            const old = seen.get(key);
            if (!old || row.value > old.value) seen.set(key, row);
        }
        PM_POWER.push(...seen.values());
    }
    return PM_POWER;
}
const pmPick = a => a[Math.floor(Math.random() * a.length)];
const pmCard = (u, display) => ({ name: display, anime: ARC_UNIVERSE_ANIME[u] || '', img: cardImg({ u, display: pmBaseName(display) }) });
function pmBuild(g) {
    g.pmUsed = g.pmUsed || [];
    const crit = Math.random() < 0.55 ? 'fort' : 'populaire';
    for (let tries = 0; tries < 60; tries++) {
        if (crit === 'fort') {
            const pool = pmPower();
            const us = [...new Set(pool.map(p => p.u))];
            const u = pmPick(us), list = pool.filter(p => p.u === u);
            if (list.length < 4) continue;
            const a = pmPick(list), b = pmPick(list.filter(x => x !== a && Math.abs(x.value - a.value) >= 10));
            if (!b) continue;
            const key = [a.name, b.name].sort().join('|'); if (g.pmUsed.includes(key)) continue;
            g.pmUsed.push(key);
            const win = a.value > b.value ? a : b;
            const [x, y] = Math.random() < .5 ? [a, b] : [b, a];
            return { u, pm: { crit, q: 'Qui est le plus fort ?', a: pmCard(u, x.name), b: pmCard(u, y.name) }, choices: [x.name, y.name], answer: win.name, pmInfo: `${win.name} est plus fort` };
        } else {
            const u = pmPick(arcUniverses()), fam = arcFamous(u);
            if (fam.length < 20) continue;
            const i = Math.floor(Math.random() * Math.min(fam.length, 60)), j = Math.floor(Math.random() * Math.min(fam.length, 60));
            if (Math.abs(i - j) < 10) continue;
            const a = fam[i], b = fam[j];
            const key = [a.display, b.display].sort().join('|'); if (g.pmUsed.includes(key)) continue;
            g.pmUsed.push(key);
            const win = i < j ? a : b;
            const [x, y] = Math.random() < .5 ? [a, b] : [b, a];
            return { u, pm: { crit, q: 'Qui est le plus populaire ?', a: pmCard(u, x.display), b: pmCard(u, y.display) }, choices: [x.display, y.display], answer: win.display, pmInfo: `${win.display} est n°${Math.min(i, j) + 1} des persos les plus connus de ${ARC_UNIVERSE_ANIME[u]}` };
        }
    }
    return null;
}
