/* =====================================================================
   MODE STREAMER TIKTOK : TikTok n'a pas de chat lisible depuis le navigateur
   (comme l'IRC de Twitch), donc le serveur se connecte au live et relaie
   chaque message au navigateur du streamer, qui l'utilise comme un message
   du chat Twitch (votes !1 !2 !3 !4, Dessine le perso…).
   ===================================================================== */
let TT_LIB = null;
const ttLib = async () => (TT_LIB = TT_LIB || await import('tiktok-live-connector'));
const TT_CONNS = new Map(); // socket.id -> { user, conn, stopped, tries, retryT }
const TT_MAX = 40;
function ttStop(sid) {
    const st = TT_CONNS.get(sid);
    if (!st) return;
    st.stopped = true;
    clearTimeout(st.retryT);
    try { if (st.conn) st.conn.disconnect().catch(() => {}); } catch (_) {}
    TT_CONNS.delete(sid);
}
io.on('connection', socket => {
    socket.on('tiktok_connect', ({ username } = {}) => {
        const user = String(username || '').trim().replace(/^@/, '').toLowerCase().replace(/[^a-z0-9_.]/g, '').slice(0, 24);
        ttStop(socket.id);
        if (!user) return socket.emit('tiktok_status', { ok: false, text: '❌ Pseudo TikTok invalide.' });
        if (TT_CONNS.size >= TT_MAX) return socket.emit('tiktok_status', { ok: false, text: '❌ Trop de lives connectés en ce moment, réessaie dans quelques minutes.' });
        const st = { user, conn: null, stopped: false, tries: 0, retryT: null };
        TT_CONNS.set(socket.id, st);
        const retry = msg => {
            if (st.stopped) return;
            st.tries++;
            const wait = Math.min(60000, 5000 * Math.pow(2, Math.min(st.tries - 1, 4)));
            socket.emit('tiktok_status', { ok: false, text: `${msg}, nouvel essai dans ${Math.round(wait / 1000)} s…` });
            clearTimeout(st.retryT);
            st.retryT = setTimeout(open, wait);
        };
        let rate = { sec: 0, n: 0 };
        async function open() {
            if (st.stopped) return;
            let lib;
            try { lib = await ttLib(); } catch (e) {
                console.warn('[tiktok] librairie absente :', e.message);
                socket.emit('tiktok_status', { ok: false, text: '❌ Le mode TikTok n’est pas disponible sur ce serveur pour le moment.' });
                return ttStop(socket.id);
            }
            const { TikTokLiveConnection, WebcastEvent, ControlEvent } = lib;
            const conn = new TikTokLiveConnection(user, { processInitialData: false, ...(process.env.TIKTOK_SIGN_KEY ? { signApiKey: process.env.TIKTOK_SIGN_KEY } : {}) });
            st.conn = conn;
            socket.emit('tiktok_status', { ok: null, text: `Connexion au live de @${user}…` });
            conn.on(WebcastEvent.CHAT, d => {
                if (st.stopped || st.conn !== conn) return;
                const sec = Math.floor(Date.now() / 1000);
                if (rate.sec !== sec) rate = { sec, n: 0 };
                if (++rate.n > 60) return; // chat très rapide : on garde 60 messages / seconde
                const u = d.user || {};
                const text = String(d.content || '').trim().slice(0, 200);
                const login = String(u.displayId || u.uniqueId || u.idStr || '').toLowerCase().slice(0, 30);
                if (!text || !login) return;
                socket.emit('tiktok_chat', { user: login, name: String(u.nickname || login).slice(0, 30), text });
            });
            conn.on(WebcastEvent.STREAM_END, () => { if (!st.stopped && st.conn === conn) retry('📴 Le live est terminé'); });
            conn.on(ControlEvent.DISCONNECTED, () => { if (!st.stopped && st.conn === conn) retry('⚠️ Live coupé'); });
            try {
                await conn.connect();
                if (st.stopped) { conn.disconnect().catch(() => {}); return; }
                st.tries = 0;
                socket.emit('tiktok_status', { ok: true, text: `✅ Connecté au live de @${user} — les viewers votent en écrivant 1, 2, 3 ou 4` });
            } catch (e) {
                if (st.stopped || st.conn !== conn) return;
                const offline = (e && e.constructor && e.constructor.name === 'UserOfflineError') || /offline|not live|isn.t online/i.test(String(e && e.message));
                retry(offline ? `⏳ @${user} n’est pas en live` : '❌ Impossible de joindre le live TikTok');
            }
        }
        open();
    });
    socket.on('tiktok_disconnect', () => ttStop(socket.id));
    socket.on('disconnect', () => ttStop(socket.id));
});


/* =====================================================================
   HALLOWEEN : cartes spéciales créées par les admins (panneau admin →
   « Cartes Halloween »). Contour Halloween, en boosters pendant l'événement
   + Booster Halloween en boutique. Clé d'une carte : « anime|perso|halloween ».
   ===================================================================== */
// Collection Halloween officielle : seulement certains persos (les plus « effrayants »), en plus de ceux ajoutés par les admins
const HW_BUILTIN = [['deathnote', 'Ryuk'], ['deathnote', 'Light Yagami'], ['tokyoghoul', 'Ken Kaneki'], ['tokyoghoul', 'Rize Kamishiro'], ['tokyoghoul', 'Juuzou Suzuya'],
    ['demonslayer', 'Muzan Kibutsuji'], ['demonslayer', 'Nezuko Kamado'], ['demonslayer', 'Akaza'], ['demonslayer', 'Doma'], ['jjk', 'Ryomen Sukuna'], ['jjk', 'Mahito'], ['jjk', 'Satoru Gojo'],
    ['naruto', 'Orochimaru'], ['naruto', 'Itachi Uchiwa'], ['naruto', 'Hidan'], ['onepiece', 'Brook'], ['onepiece', 'Gecko Moria'], ['onepiece', 'Perona'], ['onepiece', 'Trafalgar D. Water Law'],
    ['hxh', 'Hisoka Morow'], ['hxh', 'Illumi Zoldyck'], ['hxh', 'Neferpitou'], ['dragonball', 'Majin Boo'], ['dragonball', 'Cell'], ['chainsaw', 'Pochita'], ['chainsaw', 'Power'],
    ['chainsaw', 'Makima'], ['chainsaw', 'Denji'], ['fma', 'Envy'], ['bleach', 'Ulquiorra Cifer'], ['bleach', 'Mayuri Kurotsuchi'], ['bleach', 'Ichigo Kurosaki'], ['snk', 'Eren Jäger'],
    ['jojo', 'Dio Brando'], ['solo', 'Sung Jinwoo'], ['rezero', 'Rem'], ['pokemon', 'Ectoplasma'], ['pokemon', 'Mimiqui'], ['pokemon', 'Polichombr']];
let HW_BUILTIN_OK = null;
function hwBuiltin() { // noms exacts des cartes (les persos introuvables sont ignorés)
    if (HW_BUILTIN_OK) return HW_BUILTIN_OK;
    const out = [];
    for (const [u, name] of HW_BUILTIN) {
        if (!ARC_UNIVERSE_ANIME[u]) continue;
        const list = cardPool(u), q = normalizeRG(name);
        let hit = list.find(x => normalizeRG(x.display) === q);
        if (!hit) { const m = list.filter(x => normalizeRG(x.display).includes(q)); if (m.length === 1) hit = m[0]; }
        if (hit) out.push({ u, display: hit.display, builtin: true });
    }
    return (HW_BUILTIN_OK = out);
}
// l'événement s'active tout seul du 1er octobre au 2 novembre (sauf si un admin l'a coupé), ou à la main
function hwOn() {
    const h = SITE.halloween || {};
    if (h.mode === 'on') return true;
    if (h.mode === 'off') return false;
    if (h.on) return true;
    const d = new Date(), m = d.getMonth();
    return m === 9 || (m === 10 && d.getDate() <= 2);
}
const hwCards = () => {
    const own = (SITE.halloween && Array.isArray(SITE.halloween.cards)) ? SITE.halloween.cards : [];
    return hwBuiltin().filter(b => !own.some(c => c.u === b.u && c.display === b.display)).concat(own);
};
const HW_RATE = 1 / 150; // même rareté qu'une Secrète : chance par carte de booster pendant l'événement (multipliée par la chance)
SPECIAL_BY_ID.halloween = { id: 'halloween', label: 'Halloween', coins: 150 };
// toutes les cartes Halloween (même retirées du tirage : celles des joueurs restent valables)
const _cardSpecialsHw = cardSpecials;
cardSpecials = function (tier, u) {
    if (tier === 'halloween') return hwCards().filter(c => c.u === u).map(c => ({ u, display: c.display, tier: 'halloween', key: cardSpecialKey(u, c.display, 'halloween') }));
    return _cardSpecialsHw(tier, u);
};
// album : les cartes Halloween encore dans le tirage
const _cardAllSpecialsHw = cardAllSpecials;
cardAllSpecials = function (u) {
    return _cardAllSpecialsHw(u).concat(hwCards().filter(c => c.u === u && !c.off).map(c => ({ u, display: c.display, tier: 'halloween', key: cardSpecialKey(u, c.display, 'halloween') })));
};
const _openBoosterHw = openBooster;
openBooster = async function (uid, n, type = '') {
    const pool = hwCards().filter(c => !c.off && ARC_UNIVERSE_ANIME[c.u]);
    if (!hwOn() || !pool.length) return _openBoosterHw(uid, n, type === 'halloween' ? 'epique' : type);
    const luck = await cardLuck(uid);
    let k = 0;
    for (let i = 0; i < n; i++) if (Math.random() < Math.min(0.5, HW_RATE * luck)) k++;
    if (type === 'halloween') k = Math.max(1, k);
    const out = n - k > 0 ? await _openBoosterHw(uid, n - k, type === 'halloween' ? '' : type) : [];
    for (let j = 0; j < k; j++) {
        const c = pool[Math.floor(Math.random() * pool.length)];
        const card = await cardAwardSecret(uid, c.u, c.display, Math.random() < Math.min(0.9, luck / 10), 'halloween');
        out.splice(Math.floor(Math.random() * (out.length + 1)), 0, card);
    }
    return out;
};
const hwView = () => ({ on: hwOn(), cards: hwCards().map(c => ({ u: c.u, display: c.display, off: !!c.off, anime: ARC_UNIVERSE_ANIME[c.u] || c.u, img: cardImg(c) })) });
app.get('/api/admin/halloween', adminOnly(async (req, res) => {
    const u = String(req.query.u || '');
    res.json({ ok: true, ...hwView(), names: ARC_UNIVERSE_ANIME[u] ? cardPool(u).map(c => c.display) : [] });
}));
app.post('/api/admin/halloween', adminOnly(async (req, res) => {
    const b = req.body || {};
    if (!SITE.halloween || typeof SITE.halloween !== 'object') SITE.halloween = { on: false, cards: [] };
    const h = SITE.halloween;
    if (!Array.isArray(h.cards)) h.cards = [];
    if (b.action === 'toggle') { h.on = !!b.on; h.mode = b.on ? 'on' : 'off'; }
    else if (b.action === 'add') {
        // recherche stricte : nom exact, sinon un seul perso dont le nom contient ce qui est tapé
        const u = String(b.u || ''), q = normalizeRG(String(b.name || ''));
        const list = ARC_UNIVERSE_ANIME[u] ? cardPool(u) : [];
        let hit = q ? list.find(x => normalizeRG(x.display) === q) : null;
        if (!hit && q.length >= 3) { const m = list.filter(x => normalizeRG(x.display).includes(q)); if (m.length === 1) hit = m[0]; }
        const c = hit ? { u, display: hit.display } : null;
        if (!c) return res.json({ ok: false, error: 'Perso introuvable dans les cartes de cet anime (choisis-le dans la liste).' });
        const ex = h.cards.find(x => x.u === c.u && x.display === c.display);
        if (ex) ex.off = false; else h.cards.push({ u: c.u, display: c.display });
    } else if (b.action === 'remove') {
        let ex = h.cards.find(x => x.u === b.u && x.display === b.display);
        if (!ex && hwBuiltin().some(x => x.u === b.u && x.display === b.display)) h.cards.push(ex = { u: b.u, display: b.display });
        if (ex) ex.off = true; // retirée du tirage, mais celles déjà obtenues restent valables
    } else if (b.action === 'give') {
        const uid = authUserId(req);
        const ex = hwCards().find(x => x.u === b.u && x.display === b.display);
        if (!uid || !ex) return res.json({ ok: false, error: 'Carte introuvable.' });
        const card = await cardAwardSecret(uid, ex.u, ex.display, !!b.shiny, 'halloween');
        await siteSave('halloween');
        return res.json({ ok: true, ...hwView(), card });
    }
    await siteSave('halloween');
    res.json({ ok: true, ...hwView() });
}));

/* =====================================================================
   CARTES V2 : finitions (Holo, Reverse, Pailletée, Gold, Dark, Full Art,
   Manga, Galaxie, Glitch, Signée, Numérotée), raretés Éveillée et
   Légende vivante, cartes Duo, cartes de saison (Noël, Saint-Valentin,
   Été), God Pack, répliques cultes, amélioration de finition, vitrine,
   compteur mondial et cadre « Album complet ».
   Les finitions sont stockées à part (hub_kv « fin ») : la carte de base
   reste une carte normale, donc fusion / marché / échanges ne changent pas.
   ===================================================================== */
// --- nouvelles raretés spéciales ---
SPECIAL_TIERS.push({ id: 'eveillee', label: 'Éveillée', top: 2, rate: 1 / 900, coins: 100 }, { id: 'legende', label: 'Légende vivante', top: 1, rate: 1 / 6000, coins: 600 });
SPECIAL_TIERS.sort((a, b) => b.rate - a.rate);
SPECIAL_TIERS.forEach(t => { SPECIAL_BY_ID[t.id] = t; });
Object.assign(RAR_RANK, { eveillee: 5.5, legende: 7.5, duo: 4.5, noel: 5, valentin: 5, ete: 5 });
RAR_ORDER.splice(RAR_ORDER.indexOf('secrete') + 1, 0, 'eveillee');
RAR_ORDER.splice(RAR_ORDER.indexOf('cosmique') + 1, 0, 'legende');
Object.assign(DECK_BONUS, { eveillee: 22, legende: 35, noel: 18, valentin: 18, ete: 18 });
Object.assign(MARKET_HINT, { eveillee: [8000, 20000], legende: [40000, 120000], noel: [3000, 10000], valentin: [3000, 10000], ete: [3000, 10000] });

// --- finitions ---
const FINISHES = [ // de la plus rare à la plus courante ; rate = chance par carte obtenue (multipliée par la chance)
    { id: 'numbered', label: 'Numérotée', rate: 1 / 2000 }, { id: 'signed', label: 'Signée', rate: 1 / 1000 },
    { id: 'glitch', label: 'Glitch', rate: 1 / 500 }, { id: 'galaxy', label: 'Galaxie', rate: 1 / 400 },
    { id: 'manga', label: 'Manga', rate: 1 / 300 }, { id: 'fullart', label: 'Full Art', rate: 1 / 250 },
    { id: 'dark', label: 'Dark', rate: 1 / 200 }, { id: 'gold', label: 'Gold', rate: 1 / 150 },
    { id: 'glitter', label: 'Pailletée', rate: 1 / 40 }, { id: 'reverse', label: 'Reverse Holo', rate: 1 / 30 },
    { id: 'holo', label: 'Holographique', rate: 1 / 20 }
];
const FIN_IDS = FINISHES.map(f => f.id); // index 0 = la plus prestigieuse
const NUMBERED_MAX = 50; // tirage limité : 50 exemplaires de chaque carte numérotée sur tout le serveur
const finBetter = (a, b) => !b ? a : !a ? b : FIN_IDS.indexOf(a) <= FIN_IDS.indexOf(b) ? a : b;
function rollFinish(luck) {
    for (const f of FINISHES) if (Math.random() < Math.min(0.5, f.rate * (luck || 1))) return f.id;
    return null;
}
async function finAdd(uid, key, fid) {
    const g = await kvGet('fincount', key, {});
    if (fid === 'numbered' && (g.numbered || 0) >= NUMBERED_MAX) fid = 'signed';
    g[fid] = (g[fid] || 0) + 1;
    kvSet('fincount', key, g); // gardé en mémoire tout de suite, écrit en base sans bloquer l'ouverture
    const m = await kvGet('fin', String(uid), {});
    const e = m[key] = m[key] || {};
    e[fid] = (e[fid] || 0) + 1;
    let serial = null;
    if (fid === 'numbered' || fid === 'signed') { serial = g[fid]; e.ser = e.ser || {}; (e.ser[fid] = e.ser[fid] || []).push(serial); }
    kvSet('fin', String(uid), m);
    return { finish: fid, serial, serialMax: fid === 'numbered' ? NUMBERED_MAX : null, finCount: g[fid] };
}
const finBestOf = e => e ? FIN_IDS.find(f => e[f] > 0) || null : null;
const cardKeyOf = c => c.secret || SPECIAL_BY_ID[c.rarity] ? cardSpecialKey(c.u, c.name, c.rarity) : c.u + '|' + c.name;

// --- répliques cultes (tirées des citations du mode Citations) ---
let QUOTE_IDX = null;
function cardQuote(u, name) {
    if (!QUOTE_IDX) {
        QUOTE_IDX = new Map();
        try {
            Object.entries(QUOTE_UNIVERSES).forEach(([k, v]) => (v.quotes || []).forEach(q => {
                [q.speaker, ...(q.aliases || [])].forEach(n => { const kk = k + '|' + normalizeRG(n); if (!QUOTE_IDX.has(kk)) QUOTE_IDX.set(kk, []); QUOTE_IDX.get(kk).push(q.text); });
            }));
        } catch (_) {}
    }
    const n = normalizeRG(name);
    const list = QUOTE_IDX.get(u + '|' + n) || QUOTE_IDX.get(u + '|' + n.split(' ')[0]);
    return list && list.length ? list[Math.floor(Math.random() * list.length)] : null;
}
async function cardDecorate(uid, card, luck) {
    if (!card || !card.u || !card.name) return card;
    const fid = rollFinish(luck);
    if (fid) Object.assign(card, await finAdd(uid, cardKeyOf(card), fid));
    const r = RAR_RANK[card.rarity] || 0;
    if (r >= 3 || card.finish === 'signed' || card.finish === 'numbered') { const q = cardQuote(card.u, card.name); if (q) card.quote = q; }
    return card;
}
// chaque carte gagnée (jeux, boosters, fusion…) peut sortir avec une finition
const _cardAwardV2 = cardAward;
cardAward = async function (p, u, name, opts) {
    const silent = !!(opts && opts.silent);
    const out = await _cardAwardV2(p, u, name, Object.assign({}, opts || {}, { silent: true }));
    if (out && p && p.userId) await cardDecorate(p.userId, out, await cardLuck(p.userId));
    if (out && !silent && p && p.id) io.to(p.id).emit('card_gain', out);
    return out;
};
const _cardAwardSecretV2 = cardAwardSecret;
cardAwardSecret = async function (uid, u, display, shiny, tier) {
    const out = await _cardAwardSecretV2(uid, u, display, shiny, tier);
    if (out && uid) await cardDecorate(uid, out, await cardLuck(uid));
    if (out && ['eveillee', 'legende'].includes(out.rarity) && tier === out.rarity) {
        // (annonce à tout le serveur retirée) pseudoOf(uid).then(who => io.emit('rare_pull', { who, name: display, anime: ARC_UNIVERSE_ANIME[u], rarity: out.rarity, label: SPECIAL_BY_ID[out.rarity].label, shiny: !!shiny })).catch(() => {});
    }
    // (annonce à tout le serveur retirée) if (out && out.finish === 'numbered') pseudoOf(uid).then(who => io.emit('rare_pull', { who, name: display, anime: ARC_UNIVERSE_ANIME[u], rarity: out.rarity, label: `Numérotée #${out.serial}/${NUMBERED_MAX}`, shiny: !!shiny })).catch(() => {});
    return out;
};

// --- cartes de saison (comme Halloween, mais automatiques selon la date) ---
const SEASON_CARDS = {
    noel: { label: 'Noël', from: [11, 1], to: [0, 6], chars: THEME_CHARS.noel || [] },
    valentin: { label: 'Saint-Valentin', from: [1, 1], to: [1, 20], chars: [['naruto', 'Hinata Hyūga'], ['naruto', 'Sakura Haruno'], ['onepiece', 'Boa Hancock'], ['onepiece', 'Nami'], ['onepiece', 'Sanji'],
        ['demonslayer', 'Mitsuri Kanroji'], ['demonslayer', 'Nezuko Kamado'], ['snk', 'Mikasa Ackerman'], ['chainsaw', 'Makima'], ['chainsaw', 'Power'], ['rezero', 'Rem'], ['rezero', 'Emilia'],
        ['sao', 'Asuna Yuuki'], ['sao', 'Kirito'], ['fairy', 'Erza Scarlet'], ['fairy', 'Juvia Lockser'], ['fairy', 'Lucy Heartfilia'], ['bleach', 'Orihime Inoue'], ['bleach', 'Rukia Kuchiki'],
        ['dragonball', 'Bulma'], ['dragonball', 'Vegeta'], ['sds', 'Elizabeth Liones'], ['sds', 'Meliodas'], ['clover', 'Noelle Silva'], ['mushoku', 'Roxy Migurdia'], ['mushoku', 'Eris Boreas Greyrat'],
        ['cote', 'Kei Karuizawa'], ['solo', 'Cha Hae-In'], ['fma', 'Winry Rockbell'], ['jjk', 'Nobara Kugisaki'], ['tensura', 'Shuna'], ['pokemon', 'Rondoudou']] },
    ete: { label: 'Été', from: [6, 1], to: [7, 31], chars: [['onepiece', 'Monkey D. Luffy'], ['onepiece', 'Nami'], ['onepiece', 'Boa Hancock'], ['onepiece', 'Portgas D. Ace'], ['onepiece', 'Franky'], ['onepiece', 'Jinbe'],
        ['naruto', 'Naruto Uzumaki'], ['naruto', 'Kisame Hoshigaki'], ['naruto', 'Gaara'], ['dragonball', 'Son Goku'], ['dragonball', 'Bulma'], ['dragonball', 'Krillin'], ['jjk', 'Satoru Gojo'],
        ['jjk', 'Aoi Todo'], ['jjk', 'Nobara Kugisaki'], ['fairy', 'Natsu Dragneel'], ['fairy', 'Lucy Heartfilia'], ['fairy', 'Gray Fullbuster'], ['bleach', 'Ichigo Kurosaki'], ['bleach', 'Yoruichi Shihoin'],
        ['tensura', 'Rimuru Tempest'], ['tensura', 'Milim Nava'], ['rezero', 'Rem'], ['demonslayer', 'Tanjiro Kamado'], ['demonslayer', 'Zenitsu Agatsuma'], ['haikyuu', 'Shoyo Hinata'],
        ['pokemon', 'Pikachu'], ['pokemon', 'Carapuce'], ['pokemon', 'Salamèche']] }
};
function seasonActive(s) {
    const d = new Date(), m = d.getMonth(), day = d.getDate(), x = m * 100 + day, a = s.from[0] * 100 + s.from[1], b = s.to[0] * 100 + s.to[1];
    return a <= b ? x >= a && x <= b : x >= a || x <= b; // Noël chevauche le nouvel an
}
const SEASON_OK = {};
function seasonChars(id) { // noms exacts des cartes, persos introuvables ignorés
    if (SEASON_OK[id]) return SEASON_OK[id];
    const out = [];
    for (const [u, name] of SEASON_CARDS[id].chars) {
        if (!ARC_UNIVERSE_ANIME[u]) continue;
        const list = cardPool(u), q = normalizeRG(name);
        let hit = list.find(x => normalizeRG(x.display) === q);
        if (!hit) { const mm = list.filter(x => normalizeRG(x.display).includes(q)); if (mm.length === 1) hit = mm[0]; }
        if (hit) out.push({ u, display: hit.display });
    }
    return (SEASON_OK[id] = out);
}
Object.entries(SEASON_CARDS).forEach(([id, s]) => { SPECIAL_BY_ID[id] = { id, label: s.label, coins: 150 }; });
const _cardSpecialsV2 = cardSpecials;
cardSpecials = function (tier, u) {
    if (SEASON_CARDS[tier]) return seasonChars(tier).filter(c => c.u === u).map(c => ({ u, display: c.display, tier, key: cardSpecialKey(u, c.display, tier) }));
    return _cardSpecialsV2(tier, u);
};
const _cardAllSpecialsV2 = cardAllSpecials;
cardAllSpecials = function (u) { // l'album montre les cartes de la saison en cours
    return _cardAllSpecialsV2(u).concat(...Object.keys(SEASON_CARDS).filter(id => seasonActive(SEASON_CARDS[id])).map(id => cardSpecials(id, u)));
};

// --- cartes Duo (deux persos sur une carte, pris dans « Qui est le meilleur duo ? ») ---
const DUO_CARDS = () => ((QT_BY_ID.duo && QT_BY_ID.duo.items) || []).filter(i => i.imgs && i.imgs.length === 2);
const DUO_RATE = 1 / 300;
async function duoAward(uid) {
    const list = DUO_CARDS(); if (!list.length) return null;
    const d = list[Math.floor(Math.random() * list.length)];
    const isNew = await cardGive(uid, { key: 'duo|' + d.name }, false);
    if (!isNew) await ecoAddCoins(uid, 60);
    return { name: d.name, anime: d.sub || '', u: 'duo', rarity: 'duo', imgs: d.imgs, img: d.imgs[0], isNew, coins: isNew ? 0 : 60, duo: true };
}

// --- boosters : cartes de saison, cartes Duo et God Pack ---
const GOD_PACK_RATE = 1 / 500;
const _openBoosterV2 = openBooster;
openBooster = async function (uid, n, type = '') {
    const luck = await cardLuck(uid);
    if (n >= 3 && Math.random() < Math.min(0.2, GOD_PACK_RATE * luck)) { // God Pack : que des cartes rares
        const out = [];
        for (let i = 0; i < n; i++) {
            const r = Math.random(), rar = r < 0.02 ? 'cosmique' : r < 0.06 ? 'divine' : r < 0.14 ? 'eveillee' : r < 0.3 ? 'secrete' : r < 0.6 ? 'mythique' : 'legendaire';
            const pick = randomCardOfRarity(rar);
            if (!pick) continue;
            const c = pick.secret ? await cardAwardSecret(uid, pick.u, pick.display, Math.random() < 0.3, pick.tier)
                : await cardAward({ userId: uid, id: null }, pick.u, pick.display, { silent: true, shinyRate: 0.3 });
            if (c) { c.god = true; out.push(c); }
        }
        if (out.length) return out;
    }
    const out = await _openBoosterV2(uid, n, type);
    const seasons = Object.keys(SEASON_CARDS).filter(id => seasonActive(SEASON_CARDS[id]) && seasonChars(id).length);
    for (let i = 0; i < out.length; i++) {
        if ((RAR_RANK[out[i].rarity] || 0) >= 5) continue; // on ne remplace jamais une carte déjà très rare
        if (Math.random() < Math.min(0.3, DUO_RATE * luck)) { const d = await duoAward(uid); if (d) { out[i] = d; continue; } }
        if (seasons.length && Math.random() < Math.min(0.3, (1 / 150) * luck)) {
            const id = seasons[Math.floor(Math.random() * seasons.length)], list = seasonChars(id), c = list[Math.floor(Math.random() * list.length)];
            out[i] = await cardAwardSecret(uid, c.u, c.display, Math.random() < Math.min(0.9, luck / 10), id);
        }
    }
    return out;
};

